// Never submit a valid business question: this probe must stop before LLM.
const executionId = String($execution.id ?? Date.now());
const agentRunId = 'n8n-shadow-probe-' + executionId;
return [{json: {
  contract_version: '1',
  agent_run_id: agentRunId,
  question: '',
  principal: {id: 'n8n-shadow-probe', profile: 'runtime_validation'},
  correlation_metadata: {
    source: 'isolated_n8n_manual_probe',
    official_flow_modified: false
  }
}}];

const response = $input.first().json;
const expectedId = $('Build Synthetic Request').first().json.agent_run_id;
const body = response.body ?? {};
const codes = Array.isArray(body.errors) ? body.errors.map(e => e?.code) : [];
if (
  response.statusCode !== 422 ||
  body.status !== 'rejected' ||
  body.agent_run_id !== expectedId ||
  body.sql != null ||
  !codes.includes('INTERNAL_GENERATE_QUESTION_REQUIRED') ||
  typeof body.run_id !== 'string' || !body.run_id
) {
  throw new Error('Shadow validation gate mismatch: abort evidence lookup');
}
return [{json:{agent_run_id: expectedId, run_id: body.run_id}}];

const response = $input.first().json;
const expected = $('Assert Pre-LLM Rejection').first().json;
const body = response.body ?? {};
const matches = Array.isArray(body.items) ? body.items.filter(item =>
  item.agent_run_id === expected.agent_run_id &&
  item.run_id === expected.run_id &&
  item.event_type === 'generate' &&
  item.status === 'rejected' &&
  typeof item.shadow_record_id === 'string' &&
  item.shadow_record_id.length > 0
) : [];
if (response.statusCode !== 200 ||
    body.agent_run_id !== expected.agent_run_id || matches.length !== 1) {
  throw new Error('Shadow evidence is missing, mismatched or duplicated');
}
return [{json:{
  result: 'PASS',
  agent_run_id: expected.agent_run_id,
  run_id: expected.run_id,
  shadow_record_id: matches[0].shadow_record_id,
  llm_calls: 0,
  real_sql_execution: false,
  official_flow_modified: false
}}];
